    "css": "@import url(\"https://fonts.googleapis.com/css2?family=Source+Sans+Pro:wght@400;700&display=swap\");\nbody {\n  align-items: center;\n  background-color: #eef0f6;\n  display: flex;\n  font-family: \"Source Sans Pro\", sans-serif;\n  justify-content: center;\n  height: 100vh;\n}\n.card {\n  align-items: center;\n  background-color: #fff;\n  border-radius: 20px;\n  box-shadow: 0 0.4px 3.6px rgba(0, 0, 0, 0.004),\n    0 1px 8.5px rgba(0, 0, 0, 0.01), 0 1.9px 15.7px rgba(0, 0, 0, 0.019),\n    0 3.4px 28.2px rgba(0, 0, 0, 0.03), 0 6.3px 54.4px rgba(0, 0, 0, 0.047),\n    0 15px 137px rgba(0, 0, 0, 0.07);\n  display: flex;\n  flex-direction: column;\n  position: relative;\n  width: 336px;\n}\n.top {\n  background-color: #eee;\n  border-radius: 20px;\n  margin: 16px 0;\n  width: 260px;\n}\n.text {\n  box-sizing: border-box;\n  padding: 0 20px 20px;\n  width: 100%;\n}\n.title {\n  align-items: center;\n  display: flex;\n  font-size: 28px;\n  font-weight: bold;\n  margin-bottom: 4px;\n  position: relative;\n}\n.tooltip {\n  font-size: 16px;\n  font-weight: normal;\n  margin-top: 2px;\n  position: relative;\n}\n.tooltip:hover {\n  cursor: help;\n}\n.tooltip-spacing {\n  height: 20px;\n  margin: 8px;\n  position: relative;\n  width: 20px;\n}\n.tooltip-bg1 {\n  background-color: #000;\n  border-radius: 10px;\n  content: \" \";\n  display: flex;\n  height: 20px;\n  position: absolute;\n  top: 0;\n  width: 20px;\n}\n.tooltip-bg2 {\n  background-color: #fff;\n  border-radius: 8px;\n  content: \" \";\n  display: flex;\n  height: 16px;\n  left: 2px;\n  position: absolute;\n  top: 2px;\n  width: 16px;\n}\n.tooltip-text {\n  font-size: 14px;\n  font-weight: bold;\n  line-height: 20px;\n  position: relative;\n  text-align: center;\n  width: 20px;\n}\n.info {\n  color: #64686b;\n}\n.popup-bg {\n  filter: drop-shadow(0 3px 6px rgba(0, 0, 0, 0.16))\n    drop-shadow(0 3px 6px rgba(0, 0, 0, 0.23));\n  position: absolute;\n  top: -126px;\n}\n.popup-outline {\n  position: absolute;\n  top: -126px;\n}\n.popup-text {\n  border-radius: 12px;\n  box-sizing: border-box;\n  color: #fff;\n  font-size: 16px;\n  font-weight: normal;\n  left: 8px;\n  opacity: 0;\n  padding: 12px 16px;\n  position: absolute;\n  top: -117px;\n  transition: opacity 240ms 120ms cubic-bezier(0.4, 0, 0.2, 1);\n  width: 292px;\n}\n.tooltip:hover ~ .popup-text {\n  display: block;\n}\n.popup-bg {\n  opacity: 0;\n  transition: opacity 240ms 120ms cubic-bezier(0.4, 0, 0.2, 1);\n}\n.popup-outline-left {\n  stroke-dasharray: 0 426px;\n  stroke-dashoffset: 1px;\n  transition: stroke-dasharray 300ms cubic-bezier(0.4, 0, 0.2, 1);\n}\n.popup-outline-right {\n  stroke-dasharray: 352px 352px;\n  stroke-dashoffset: -352px;\n  transition: stroke-dashoffset 300ms cubic-bezier(0.4, 0, 0.2, 1);\n}\n.tooltip:hover ~ .popup-text {\n  opacity: 1;\n}\n.tooltip:hover ~ .popup-bg {\n  opacity: 1;\n  transition: opacity 240ms 120ms cubic-bezier(0.4, 0, 0.2, 1);\n}\n.tooltip:hover ~ .popup-outline .popup-outline-left {\n  stroke-dasharray: 426px 426px;\n  transition: stroke-dasharray 300ms cubic-bezier(0.4, 0, 0.2, 1);\n}\n.tooltip:hover ~ .popup-outline .popup-outline-right {\n  stroke-dashoffset: 0;\n  transition: stroke-dashoffset 300ms cubic-bezier(0.4, 0, 0.2, 1);\n}\n\n.buttons {\n  display: flex;\n  margin-top: 8px;\n  width: 100%;\n}\n.button {\n  align-items: center;\n  background: #edf1f7;\n  border-radius: 10px;\n  cursor: pointer;\n  display: flex;\n  height: 50px;\n  justify-content: center;\n  margin: 0 5px 28px 20px;\n  width: 100%;\n}\n\n.button:last-child {\n  margin: 0 20px 20px 5px;\n}\n\n.button-primary {\n  background-color: #0060f6;\n  color: #fff;\n}",
