    "css": "@import url('https://fonts.googleapis.com/css2?family=Quicksand:wght@300;400;500;600;700&display=swap');\n*\n{\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n  font-family: 'Quicksand', sans-serif;\n}\nbody \n{\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  min-height: 100vh;\n  background: #000;\n}\nsection \n{\n  position: absolute;\n  width: 100vw;\n  height: 100vh;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  gap: 2px;\n  flex-wrap: wrap;\n  overflow: hidden;\n}\nsection::before \n{\n  content: '';\n  position: absolute;\n  width: 100%;\n  height: 100%;\n  background: linear-gradient(#000,#0f0,#000);\n  animation: animate 5s linear infinite;\n}\n@keyframes animate \n{\n  0%\n  {\n    transform: translateY(-100%);\n  }\n  100%\n  {\n    transform: translateY(100%);\n  }\n}\nsection span \n{\n  position: relative;\n  display: block;\n  width: calc(6.25vw - 2px);\n  height: calc(6.25vw - 2px);\n  background: #181818;\n  z-index: 2;\n  transition: 1.5s;\n}\nsection span:hover \n{\n  background: #0f0;\n  transition: 0s;\n}\n\nsection .signin\n{\n  position: absolute;\n  width: 400px;\n  background: #222;  \n  z-index: 1000;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  padding: 40px;\n  border-radius: 4px;\n  box-shadow: 0 15px 35px rgba(0,0,0,9);\n}\nsection .signin .content \n{\n  position: relative;\n  width: 100%;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  flex-direction: column;\n  gap: 40px;\n}\nsection .signin .content h2 \n{\n  font-size: 2em;\n  color: #0f0;\n  text-transform: uppercase;\n}\nsection .signin .content .form \n{\n  width: 100%;\n  display: flex;\n  flex-direction: column;\n  gap: 25px;\n}\nsection .signin .content .form .inputBox\n{\n  position: relative;\n  width: 100%;\n}\nsection .signin .content .form .inputBox input \n{\n  position: relative;\n  width: 100%;\n  background: #333;\n  border: none;\n  outline: none;\n  padding: 25px 10px 7.5px;\n  border-radius: 4px;\n  color: #fff;\n  font-weight: 500;\n  font-size: 1em;\n}\nsection .signin .content .form .inputBox i \n{\n  position: absolute;\n  left: 0;\n  padding: 15px 10px;\n  font-style: normal;\n  color: #aaa;\n  transition: 0.5s;\n  pointer-events: none;\n}\n.signin .content .form .inputBox input:focus ~ i,\n.signin .content .form .inputBox input:valid ~ i\n{\n  transform: translateY(-7.5px);\n  font-size: 0.8em;\n  color: #fff;\n}\n.signin .content .form .links \n{\n  position: relative;\n  width: 100%;\n  display: flex;\n  justify-content: space-between;\n}\n.signin .content .form .links a \n{\n  color: #fff;\n  text-decoration: none;\n}\n.signin .content .form .links a:nth-child(2)\n{\n  color: #0f0;\n  font-weight: 600;\n}\n.signin .content .form .inputBox input[type=\"submit\"]\n{\n  padding: 10px;\n  background: #0f0;\n  color: #000;\n  font-weight: 600;\n  font-size: 1.35em;\n  letter-spacing: 0.05em;\n  cursor: pointer;\n}\ninput[type=\"submit\"]:active\n{\n  opacity: 0.6;\n}\n@media (max-width: 900px)\n{\n  section span \n  {\n    width: calc(10vw - 2px);\n    height: calc(10vw - 2px);\n  }\n}\n@media (max-width: 600px)\n{\n  section span \n  {\n    width: calc(20vw - 2px);\n    height: calc(20vw - 2px);\n  }\n}",
